From 33406f684cd4da3927d2468d66d12d8318f65296 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:45:52 +0100
Subject: [PATCH] applets/pager: open the Overview when clicking the current
 desktop

Clicking the current desktop in the pager could only do nothing or show
the desktop. This adds a "Shows the overview" option that opens KWin's
Overview and makes it the default, giving a mouse way to reach it.

BUG: 404618
---
 applets/pager/main.xml              |  3 ++-
 applets/pager/pagermodel.cpp        | 25 +++++++++++++++++--------
 applets/pager/pagermodel.h          |  8 ++++----
 applets/pager/qml/configGeneral.qml |  8 ++++++++
 applets/pager/qml/main.qml          |  2 +-
 5 files changed, 32 insertions(+), 14 deletions(-)

diff --git a/applets/pager/main.xml b/applets/pager/main.xml
index d47b935b1e..835c701745 100644
--- a/applets/pager/main.xml
+++ b/applets/pager/main.xml
@@ -36,8 +36,9 @@
         <choices>
             <choice name="DoNothing"/>
             <choice name="ShowDesktop"/>
+            <choice name="ShowOverview"/>
         </choices>
-        <default>0</default>
+        <default>2</default>
     </entry>
     <entry name="pagerLayout" type="Enum">
         <label>The layout style used for the presentation.</label>
diff --git a/applets/pager/pagermodel.cpp b/applets/pager/pagermodel.cpp
index 6e476f3d15..859f8af590 100644
--- a/applets/pager/pagermodel.cpp
+++ b/applets/pager/pagermodel.cpp
@@ -40,7 +40,8 @@ public:

     PagerType pagerType = VirtualDesktops;
     bool enabled = false;
-    bool showDesktop = false;
+    // 0: none, 1: show desktop, 2: show overview
+    int actionOnClick = 0;

     bool showOnlyCurrentScreen = false;
     QRect screenGeometry;
@@ -284,17 +285,17 @@ bool PagerModel::shouldShowPager() const
     return (d->pagerType == VirtualDesktops) ? d->virtualDesktopInfo->numberOfDesktops() > 1 : d->activityInfo->numberOfRunningActivities() > 1;
 }

-bool PagerModel::showDesktop() const
+int PagerModel::actionOnClick() const
 {
-    return d->showDesktop;
+    return d->actionOnClick;
 }

-void PagerModel::setShowDesktop(bool show)
+void PagerModel::setActionOnClick(int action)
 {
-    if (d->showDesktop != show) {
-        d->showDesktop = show;
+    if (d->actionOnClick != action) {
+        d->actionOnClick = action;

-        Q_EMIT showDesktopChanged();
+        Q_EMIT actionOnClickChanged();
     }
 }

@@ -486,11 +487,19 @@ void PagerModel::moveWindow(const QModelIndex &index,
 void PagerModel::changePage(int page)
 {
     if (currentPage() == page) {
-        if (d->showDesktop) {
+        if (d->actionOnClick == 1) {
             QDBusConnection::sessionBus().asyncCall(QDBusMessage::createMethodCall(QLatin1String("org.kde.plasmashell"),
                                                                                    QLatin1String("/PlasmaShell"),
                                                                                    QLatin1String("org.kde.PlasmaShell"),
                                                                                    QLatin1String("toggleDashboard")));
+        } else if (d->actionOnClick == 2) {
+            // HACK this seems to be the only D-Bus interface for opening the Overview
+            QDBusMessage message = QDBusMessage::createMethodCall(QLatin1String("org.kde.kglobalaccel"),
+                                                                  QLatin1String("/component/kwin"),
+                                                                  QLatin1String("org.kde.kglobalaccel.Component"),
+                                                                  QLatin1String("invokeShortcut"));
+            message.setArguments({QStringLiteral("Overview")});
+            QDBusConnection::sessionBus().asyncCall(message);
         }
     } else {
         if (d->pagerType == VirtualDesktops) {
diff --git a/applets/pager/pagermodel.h b/applets/pager/pagermodel.h
index 02613b42dc..31b0e20b71 100644
--- a/applets/pager/pagermodel.h
+++ b/applets/pager/pagermodel.h
@@ -22,7 +22,7 @@ class PagerModel : public QAbstractListModel, public QQmlParserStatus
     Q_PROPERTY(PagerType pagerType READ pagerType WRITE setPagerType NOTIFY pagerTypeChanged)
     Q_PROPERTY(bool enabled READ enabled WRITE setEnabled NOTIFY enabledChanged)
     Q_PROPERTY(bool shouldShowPager READ shouldShowPager NOTIFY shouldShowPagerChanged)
-    Q_PROPERTY(bool showDesktop READ showDesktop WRITE setShowDesktop NOTIFY showDesktopChanged)
+    Q_PROPERTY(int actionOnClick READ actionOnClick WRITE setActionOnClick NOTIFY actionOnClickChanged)
     Q_PROPERTY(bool showOnlyCurrentScreen READ showOnlyCurrentScreen WRITE setShowOnlyCurrentScreen NOTIFY showOnlyCurrentScreenChanged)
     Q_PROPERTY(QString screenName READ screenName WRITE setScreenName NOTIFY screenNameChanged)
     Q_PROPERTY(QRect screenGeometry READ screenGeometry WRITE setScreenGeometry NOTIFY screenGeometryChanged)
@@ -59,8 +59,8 @@ public:

     bool shouldShowPager() const;

-    bool showDesktop() const;
-    void setShowDesktop(bool show);
+    int actionOnClick() const;
+    void setActionOnClick(int action);

     bool showOnlyCurrentScreen() const;
     void setShowOnlyCurrentScreen(bool show);
@@ -100,7 +100,7 @@ Q_SIGNALS:
     void pagerTypeChanged() const;
     void enabledChanged() const;
     void shouldShowPagerChanged() const;
-    void showDesktopChanged() const;
+    void actionOnClickChanged() const;
     void showOnlyCurrentScreenChanged() const;
     void screenGeometryChanged() const;
     void screenNameChanged() const;
diff --git a/applets/pager/qml/configGeneral.qml b/applets/pager/qml/configGeneral.qml
index 23074d9ab6..96bf93cbbb 100644
--- a/applets/pager/qml/configGeneral.qml
+++ b/applets/pager/qml/configGeneral.qml
@@ -132,5 +132,13 @@ KCM.SimpleKCM {
             checked: root.cfg_currentDesktopSelected === 1
             onToggled: if (checked) root.cfg_currentDesktopSelected = 1;
         }
+
+        QQC2.RadioButton {
+            id: showsOverviewRadio
+            QQC2.ButtonGroup.group: currentDesktopSelectedGroup
+            text: i18nc("option:check completes the sentence 'Selecting current activity/virtual desktop shows the overview'", "Shows the overview")
+            checked: root.cfg_currentDesktopSelected === 2
+            onToggled: if (checked) root.cfg_currentDesktopSelected = 2;
+        }
     }
 }
diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..84beb60105 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -143,7 +143,7 @@ PlasmoidItem {

         enabled: root.visible

-        showDesktop: (Plasmoid.configuration.currentDesktopSelected === 1)
+        actionOnClick: Plasmoid.configuration.currentDesktopSelected

         showOnlyCurrentScreen: Plasmoid.configuration.showOnlyCurrentScreen
         screenName: root.Screen.name
-- 
